function t(){return{tasks:[{text:"Какое правило подсчёта применяется, если выбор объекта A и объекта B происходит последовательно и независимо?",type:"choice",answer:"Правило произведения",options:["Правило суммы","Правило произведения","Правило Байеса","Правило дополнения"],hint:"Пару (A, B) можно выбрать m × n способами",difficulty:"Легко"},{text:"Чему равно число перестановок из n различных объектов?",type:"choice",answer:"n!",options:["n²","n!","n(n−1)","2ⁿ"],hint:"Pₙ = n! = 1 × 2 × 3 × ... × n",difficulty:"Легко"},{text:"Чем размещение отличается от сочетания?",type:"choice",answer:"В размещении важен порядок, в сочетании — нет",options:["Размещение — только для чисел, сочетание — для букв","В размещении важен порядок, в сочетании — нет","Это одно и то же","Сочетание всегда больше размещения"],hint:"Aₙᵏ учитывает порядок, Cₙᵏ — нет",difficulty:"Средне"},{text:"По какой формуле считается число сочетаний Cₙᵏ?",type:"choice",answer:"n! / (k! × (n − k)!)",options:["n! / (n − k)!","n! / (k! × (n − k)!)","n × k","n! / k!"],hint:"Это коэффициенты треугольника Паскаля",difficulty:"Средне"},{text:"Как называется величина m/n в классическом определении вероятности?",type:"choice",answer:"Вероятность события A: P(A) = m/n",options:["Дисперсия","Математическое ожидание","Вероятность события A: P(A) = m/n","Условная вероятность"],hint:"m — число благоприятных исходов, n — общее число равновозможных",difficulty:"Легко"},{text:"Чему равна вероятность достоверного события P(Ω)?",type:"choice",answer:"1",options:["0","1","0,5","Не определена"],hint:"Достоверное событие происходит всегда",difficulty:"Легко"},{text:"Что означает A ∩ B в алгебре событий?",type:"choice",answer:"Произошли оба события одновременно",options:["Произошло хотя бы одно из событий","Событие A не произошло","Произошли оба события одновременно","Ни одно событие не произошло"],hint:"Это произведение (пересечение) событий",difficulty:"Средне"},{text:"Какая формула задаёт условную вероятность P(A|B)?",type:"choice",answer:"P(A ∩ B) / P(B)",options:["P(A) × P(B)","P(A ∩ B) / P(B)","P(A) + P(B)","P(A) / P(B ∩ A)"],hint:"Вероятность A при условии, что B уже произошло",difficulty:"Средне"},{text:"Для чего используется формула Байеса?",type:"choice",answer:"Пересчитать вероятность гипотезы после наступления события",options:["Найти число сочетаний","Пересчитать вероятность гипотезы после наступления события","Вычислить дисперсию","Найти математическое ожидание"],hint:"P(Hᵢ|A) = P(Hᵢ) × P(A|Hᵢ) / P(A)",difficulty:"Сложно"},{text:"Что измеряет дисперсия D(X) случайной величины?",type:"choice",answer:"Разброс значений вокруг математического ожидания",options:["Среднее значение величины","Разброс значений вокруг математического ожидания","Число исходов испытания","Вероятность одного конкретного исхода"],hint:"D(X) = M[(X − M(X))²]",difficulty:"Средне"}]}}export{t as default};
